<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/src/bootstrap.php';
?><!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pages détaillées des circuits — MIARADI</title>
<style>
:root{--red:#922D20;--paper:#f7f6fb;--ink:#292633;--muted:#898596;--line:#e9e6ef;--lav:#f2edff;--purple:#7061d3}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.55 Inter,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}.top{height:70px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 28px;position:sticky;top:0;z-index:2}.brand{display:flex;align-items:center;gap:12px;font-weight:850;letter-spacing:.06em}.brand img{width:42px;height:42px;object-fit:contain;background:#fbf4f0;border-radius:12px;padding:4px}.brand small{display:block;font-size:9px;color:#9993a4;letter-spacing:.16em}.top a{color:var(--red);text-decoration:none;font-weight:700}.wrap{max-width:1450px;margin:auto;padding:30px 26px 70px}.heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:.17em;text-transform:uppercase;color:var(--red);font-weight:800}.heading h1{font-size:30px;letter-spacing:-.04em;margin:5px 0}.heading p{margin:0;color:var(--muted)}.layout{display:grid;grid-template-columns:310px minmax(0,1fr);gap:20px;align-items:start}.panel{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:0 5px 22px #30205a05}.panel h2{font-size:19px;margin:0 0 15px}.list{display:grid;gap:8px}.page-item{display:block;width:100%;text-align:left;background:#fff;border:1px solid var(--line);border-radius:11px;padding:13px;color:var(--ink)}.page-item.active,.page-item:hover{border-color:#cfc6fa;background:#f7f4ff}.page-item strong{display:block;font-size:13px}.page-item small{color:var(--muted);display:block;margin-top:3px}.empty{color:var(--muted);font-size:12px;padding:15px 0}.btn{border:1px solid var(--red);background:var(--red);color:#fff;border-radius:10px;padding:10px 14px;font-weight:750;font-size:12px}.btn:hover{filter:brightness(.94)}.btn.secondary{background:#fff;border-color:var(--line);color:#5e596b}.btn.soft{background:var(--lav);border-color:var(--lav);color:var(--purple)}.toolbar{display:flex;gap:8px;flex-wrap:wrap}.field{display:grid;gap:6px;margin:13px 0;font-weight:700;font-size:12px}.field input,.field select,.field textarea{width:100%;border:1px solid #e4e0ea;background:#fdfcff;border-radius:9px;padding:11px 12px;color:var(--ink);font-weight:400;min-width:0}.field textarea{min-height:90px;resize:vertical}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.separator{height:1px;background:var(--line);margin:22px 0}.day{border:1px solid var(--line);border-radius:13px;padding:16px;margin:13px 0;background:#fff}.day-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:5px}.day-head strong{font-size:14px}.image-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;gap:8px;align-items:end}.notice{min-height:22px;margin:10px 0;color:var(--red);font-weight:700;font-size:12px}.help{font-size:11px;color:var(--muted);font-weight:400}.toggle{display:flex;align-items:center;gap:9px;font-weight:700;font-size:12px}.toggle input{width:17px;height:17px;accent-color:var(--red)}.tag{display:inline-flex;padding:4px 8px;background:#eaf7ef;color:#23824b;border-radius:7px;font-size:10px;font-weight:800}.preview-link{display:inline-block;margin-top:10px;color:var(--red);font-weight:750;text-decoration:none}.hidden{display:none!important}
@media(max-width:900px){.layout{grid-template-columns:1fr}.list{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.top{padding:0 13px}.wrap{padding:20px 12px}.panel{padding:16px}.heading{display:block}.heading h1{font-size:25px}.grid2,.image-row{grid-template-columns:1fr}.list{grid-template-columns:1fr}}
</style></head><body>
<header class="top"><div class="brand"><img src="../../../assets/miaradi-logo.png" alt=""><span>MIARADI<small>ESPACE ADMIN · PAGES CIRCUITS</small></span></div><div class="toolbar"><a href="index.php">← Retour à l’administration</a><button class="btn secondary" id="logout">Déconnexion</button></div></header>
<main class="wrap"><div class="heading"><div><div class="eyebrow">Éditeur de pages de voyage</div><h1>Pages détaillées des circuits</h1><p>Créez des pages immersives avec une introduction, un hero et un programme jour par jour.</p></div><button class="btn" id="new-page">＋ Nouvelle page</button></div>
<div class="layout"><aside class="panel"><h2>Pages enregistrées</h2><div id="pages-list" class="list"><div class="empty">Chargement…</div></div><div class="separator"></div><p class="help">Une page détaillée est associée à un circuit du catalogue. Le contenu peut rester en brouillon jusqu’à sa publication.</p></aside>
<section class="panel"><form id="page-form"><input type="hidden" id="page-id">
<div class="grid2"><label class="field">Circuit du catalogue<select id="circuit-id" required><option value="">Chargement des circuits…</option></select></label><label class="field">Image principale (URL ou chemin local)<input id="hero-image" placeholder="assets/images/hero.jpg"><span class="help">Utilisez une image locale ou une URL HTTPS fiable.</span></label></div>
<div class="grid2"><label class="field">Titre principal (FR)<input id="hero-fr" placeholder="Madagascar du Sud au Nord"></label><label class="field">Titre principal (EN)<input id="hero-en" placeholder="Madagascar from South to North"></label></div>
<div class="grid2"><label class="field">Introduction (FR)<textarea id="intro-fr" placeholder="Présentez l’esprit du voyage, ses régions et ses expériences."></textarea></label><label class="field">Introduction (EN)<textarea id="intro-en" placeholder="Describe the journey, its regions and experiences."></textarea></label></div>
<div class="separator"></div><div class="day-head"><div><h2 style="margin:0">Programme jour par jour</h2><span class="help">Ajoutez chaque étape et jusqu’à 5 images par journée.</span></div><button type="button" class="btn soft" id="add-day">＋ Ajouter une journée</button></div>
<div id="days"></div>
<div class="separator"></div><label class="toggle"><input type="checkbox" id="published"> Publier cette page sur le site</label>
<p class="help">La publication rend la page accessible via le lien de prévisualisation public. Vérifiez les textes et les images avant de publier.</p>
<div class="toolbar"><button class="btn" type="submit" id="save">Enregistrer la page</button><button class="btn secondary" type="button" id="reset">Annuler</button><button class="btn secondary hidden" type="button" id="delete">Supprimer</button></div><div class="notice" id="notice" role="status" aria-live="polite"></div><a id="preview" class="preview-link hidden" target="_blank" rel="noopener">↗ Ouvrir la page publique</a>
</form></section></div></main>
<script>
(() => {
'use strict';
const $=s=>document.querySelector(s); const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let csrf='', pages=[], circuits=[], selected=null;
async function request(path,options={}){const headers={'Accept':'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(options.mutate?{'X-CSRF-Token':csrf}:{})};const res=await fetch('../api/'+path,{credentials:'same-origin',...options,headers});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error?.message||'Une erreur est survenue.');return data;}
function note(s){$('#notice').textContent=s||''}
function resetForm(){selected=null;$('#page-id').value='';$('#circuit-id').value='';$('#hero-image').value='';$('#hero-fr').value='';$('#hero-en').value='';$('#intro-fr').value='';$('#intro-en').value='';$('#published').checked=false;$('#days').innerHTML='';$('#delete').classList.add('hidden');$('#preview').classList.add('hidden');$('#save').textContent='Enregistrer la page';note('');renderList();}
function addDay(day={}){const n=$('#days').children.length+1;const section=document.createElement('section');section.className='day';section.innerHTML='<div class="day-head"><strong>Journée <span class="day-number">'+n+'</span></strong><button class="btn secondary remove-day" type="button">Retirer</button></div><div class="grid2"><label class="field">Titre de l’étape *<input class="day-title" required maxlength="220" placeholder="Antananarivo – Antsirabe" value="'+esc(day.title||'')+'"></label><label class="field">Sous-titre<input class="day-subtitle" maxlength="220" placeholder="Route vers les Hautes Terres" value="'+esc(day.subtitle||'')+'"></label></div><label class="field">Description<textarea class="day-description" placeholder="Décrivez les visites, paysages et rencontres…">'+esc(day.description||'')+'</textarea></label><label class="field">Nuitée<input class="day-overnight" maxlength="500" placeholder="Nuitée : hôtel à…" value="'+esc(day.overnight||'')+'"></label><div class="images"><div class="day-head"><strong>Images de l’étape</strong><button class="btn soft add-image" type="button">＋ Image</button></div></div>';
const imgs=section.querySelector('.images');(Array.isArray(day.images)?day.images:[]).forEach(img=>addImage(imgs,img));if(!day.images||!day.images.length)addImage(imgs);section.querySelector('.remove-day').addEventListener('click',()=>{section.remove();renumberDays()});section.querySelector('.add-image').addEventListener('click',()=>{if(imgs.querySelectorAll('.image-row').length>=5){note('Maximum 5 images par journée.');return;}addImage(imgs);});$('#days').appendChild(section);renumberDays();}
function addImage(container,img={}){const row=document.createElement('div');row.className='image-row';row.innerHTML='<label class="field">URL / chemin image<input class="image-url" placeholder="https://… ou assets/…" value="'+esc(img.url||'')+'"></label><label class="field">Texte alternatif<input class="image-alt" placeholder="Description de la photo" value="'+esc(img.alt||'')+'"></label><button class="btn secondary remove-image" type="button">×</button>';row.querySelector('.remove-image').addEventListener('click',()=>row.remove());container.appendChild(row);}
function renumberDays(){[...$('#days').children].forEach((el,i)=>el.querySelector('.day-number').textContent=i+1)}
function collectDays(){return [...$('#days').children].map(el=>({title:el.querySelector('.day-title').value.trim(),subtitle:el.querySelector('.day-subtitle').value.trim(),description:el.querySelector('.day-description').value.trim(),overnight:el.querySelector('.day-overnight').value.trim(),images:[...el.querySelectorAll('.image-row')].map(row=>({url:row.querySelector('.image-url').value.trim(),alt:row.querySelector('.image-alt').value.trim()})).filter(x=>x.url)}))}
function renderList(){const el=$('#pages-list');if(!pages.length){el.innerHTML='<div class="empty">Aucune page détaillée créée pour le moment.</div>';return;}el.innerHTML=pages.map(p=>'<button type="button" class="page-item '+(selected&&Number(selected.id)===Number(p.id)?'active':'')+'" data-id="'+Number(p.id)+'"><strong>'+esc(p.hero_title_fr||p.title_fr)+'</strong><small>'+esc(p.title_fr)+' · '+(p.is_published?'<span class="tag">Publiée</span>':'Brouillon')+'</small><small>'+((p.days||[]).length)+' journée(s)</small></button>').join('');el.querySelectorAll('[data-id]').forEach(b=>b.addEventListener('click',()=>openPage(pages.find(p=>Number(p.id)===Number(b.dataset.id)))));}
function fillCircuitSelect(selectedId){$('#circuit-id').innerHTML='<option value="">Choisir un circuit…</option>'+circuits.map(c=>'<option value="'+Number(c.id)+'">'+esc(c.title_fr)+' ('+esc(c.slug)+')</option>').join('');if(selectedId)$('#circuit-id').value=String(selectedId);}
function openPage(p){if(!p)return;selected=p;$('#page-id').value=p.id;fillCircuitSelect(p.circuit_id);$('#hero-image').value=p.hero_image||'';$('#hero-fr').value=p.hero_title_fr||'';$('#hero-en').value=p.hero_title_en||'';$('#intro-fr').value=p.intro_fr||'';$('#intro-en').value=p.intro_en||'';$('#published').checked=!!p.is_published;$('#days').innerHTML='';(p.days||[]).forEach(addDay);$('#delete').classList.remove('hidden');$('#save').textContent='Enregistrer les modifications';$('#preview').classList.toggle('hidden',!p.is_published);if(p.is_published)$('#preview').href='../circuit-detail.php?slug='+encodeURIComponent(p.slug);note('');renderList();}
async function load(){try{const s=await request('admin/session.php');if(!s.data?.authenticated){location.replace('login.php');return;}csrf=s.data.csrfToken||'';const data=await request('admin/circuit-pages.php');pages=data.data||[];circuits=data.circuits||[];fillCircuitSelect();renderList();}catch(e){note(e.message);}}
$('#new-page').addEventListener('click',()=>{resetForm();addDay();});
$('#add-day').addEventListener('click',()=>{if($('#days').children.length>=60){note('Maximum 60 journées par circuit.');return;}addDay();note('')});
$('#reset').addEventListener('click',resetForm);
$('#page-form').addEventListener('submit',async e=>{e.preventDefault();note('');const circuitId=Number($('#circuit-id').value);if(!circuitId){note('Sélectionnez un circuit du catalogue.');return;}const days=collectDays();if(!days.length){note('Ajoutez au moins une journée au programme.');return;}if(days.some(d=>!d.title)){note('Chaque journée doit avoir un titre.');return;}const payload={circuit_id:circuitId,hero_image:$('#hero-image').value.trim(),hero_title_fr:$('#hero-fr').value.trim(),hero_title_en:$('#hero-en').value.trim(),intro_fr:$('#intro-fr').value.trim(),intro_en:$('#intro-en').value.trim(),is_published:$('#published').checked,days};const id=$('#page-id').value;if(id)payload.id=Number(id);$('#save').disabled=true;try{const r=await request('admin/circuit-pages.php',{method:id?'PATCH':'POST',mutate:true,body:JSON.stringify(payload)});note('Page enregistrée avec succès.');await load();const p=pages.find(x=>Number(x.id)===Number(r.data.id));if(p)openPage(p);}catch(err){note(err.message)}finally{$('#save').disabled=false;}});
$('#delete').addEventListener('click',async()=>{if(!selected||!confirm('Supprimer cette page détaillée ? Le circuit du catalogue sera conservé.'))return;try{await request('admin/circuit-pages.php?id='+selected.id,{method:'DELETE',mutate:true});resetForm();await load();note('Page supprimée.');}catch(e){note(e.message)}});
$('#logout').addEventListener('click',async()=>{try{await request('admin/session.php',{method:'POST',mutate:true,body:JSON.stringify({action:'logout'})})}catch(_){}location.replace('login.php')});
load();
})();
</script></body></html>